namespace MDNote {public partial class MainWindow {
    internal static string[] DefaultFunctionKeys(){return new[]{"edit","source","heading","list","task","quote","inline","block","table","outline","previousTab","nextTab"};}
    static string[] functionKeys=DefaultFunctionKeys();
    static readonly string[] ShortcutIds={"none","edit","source","strike","mark","superscript","subscript","color","clearColor","size","heading","h1","h2","h3","h4","h5","h6","paragraph","list","bullet","number","task","check","quote","rule","inline","block","link","image","table","rowAdd","rowRemove","columnAdd","columnRemove","tableDelete","tableParagraph","dark","wrap","outline","previousTab","nextTab","zoomIn","zoomOut","zoomReset"};
    static readonly string[] ShortcutLabels={"지정 안 함","수정 모드","원문 편집","취소선","형광펜","위 첨자","아래 첨자","글자색 선택","글자색 초기화","글자 크기 선택","마지막 선택 제목","제목 1","제목 2","제목 3","제목 4","제목 5","제목 6","일반 문단","마지막 선택 목록","글머리 기호 목록","번호 목록","체크리스트 삽입/해제","완료/미완료 전환","인용","구분선","인라인 코드","코드 블록","링크","이미지","표 삽입","행 추가","행 제거","열 추가","열 제거","표 삭제","아래 문단 추가","다크 모드","자동 줄바꿈","아웃라인","이전 탭","다음 탭","글자 확대","글자 축소","확대율 초기화"};
    internal static bool ValidShortcut(string id){return Array.IndexOf(ShortcutIds,id)>=0;}
    /* B3: an assigned F-key runs the same control the toolbar or the formatting menu runs, instead
       of a second copy of the command. A wrong copy was how F3-F12 stayed silent after the rich
       engine was removed: the live commands exist, but the dispatch still spoke to the old ones. */
    static void Press(FrameworkElement control){var button=control as ButtonBase;if(button!=null){button.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));return;}var item=control as MenuItem;if(item!=null)item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));}
    /* F1..F12 belong to the field that has focus: the find/replace boxes, the editable size box and
       any dialog input keep the key, and only the body runs the mapped command. The editor's surface
       is a TextArea, not a TextBox, so it is never caught here. */
    static bool FieldOwnsFunctionKey(IInputElement focused){return focused is TextBox||focused is ComboBox||focused is ComboBoxItem;}
    // Probe seam: a headless run has no real keyboard focus, so the handler asks here when set.
    internal static Func<IInputElement> FunctionKeyFocus=null;
    void SetupFunctionKeys(){var settings=AddMenu(topMenu,"단축키");topMenu.Items.Remove(settings);topMenu.Items.Insert(3,settings);settings.Click+=delegate{ShowShortcutSettings();};PreviewKeyDown+=delegate(object sender,KeyEventArgs e){var focused=FunctionKeyFocus!=null?FunctionKeyFocus():Keyboard.FocusedElement;if(FieldOwnsFunctionKey(focused))return;/* Same rule as Keys: an IME-owned key never runs an F-key function (F6-F10 are IME conversions while composing). */if(e.Key==Key.ImeProcessed)return;Key key=e.Key==Key.System?e.SystemKey:e.Key;int index=(int)key-(int)Key.F1;if(index<0||index>=12||Keyboard.Modifiers!=ModifierKeys.None)return;if(functionKeys[index]=="none")return;/* b58: an F-key that opens a dialog or moves focus (size/table/link/image/color) must put a live IME syllable into the document first; otherwise AvalonEdit cancels it when the focus leaves. */CommitCompositionForKeyboardCommand();e.Handled=true;ExecuteFunction(functionKeys[index]);};
        BindShortcutTip(editButton,"edit","수정 시작/종료","Ctrl+E");BindShortcutTip(preview,"source","원문 편집 켜기/끄기",null);BindShortcutTip(headingButton,"heading","마지막 선택 제목 적용",null);BindShortcutTip(listButton,"list","마지막 선택 목록 적용",null);BindShortcutTip(taskButton,"task","체크리스트 삽입",null);BindShortcutTip(quoteButton,"quote","인용문 켜기/끄기",null);BindShortcutTip(ruleButton,"rule","구분선 삽입",null);BindShortcutTip(codeButton,"inline","인라인 코드 켜기/끄기",null);BindShortcutTip(blockButton,"block","코드 블록 삽입",null);BindShortcutTip(linkButton,"link","링크(URL) 삽입","Ctrl+K");BindShortcutTip(imageButton,"image","이미지 삽입","Ctrl+Shift+I");BindShortcutTip(tableButton,"table","표 삽입",null);BindShortcutTip(outlineButton,"outline","아웃라인",null);BindShortcutTip(quickDark,"dark","다크 모드",null);BindShortcutTip(strikeButton,"strike","취소선 켜기/끄기",null);BindShortcutTip(colorArrow,"color","글자색 선택",null);BindShortcutTip(sizes,"size","선택한 글자 크기 설정",null);for(int i=0;i<Math.Min(6,tableActions.Count);i++)BindShortcutTip(tableActions[i],new[]{"rowAdd","rowRemove","columnAdd","columnRemove","tableDelete","tableParagraph"}[i],new[]{"행 추가","행 제거","열 추가","열 제거","표 삭제","아래 문단 추가"}[i],null);for(int i=0;i<headingButtons.Count;i++)BindShortcutTip(headingButtons[i],"h"+(i+1),"H"+(i+1),null);
    }
    void BindShortcutTip(FrameworkElement control,string command,string caption,string existing){ToolTipService.SetShowOnDisabled(control,true);control.ToolTip=T(caption);control.ToolTipOpening+=delegate{var keys=new List<string>();if(!String.IsNullOrEmpty(existing))keys.Add(existing);for(int i=0;i<12;i++)if(functionKeys[i]==command)keys.Add("F"+(i+1));control.ToolTip=T(caption)+(keys.Count==0?"":" ("+String.Join(" / ",keys)+")");};}
    /* The View menu prints the function key the command runs on today; empty when it is unassigned. */
    internal static string FunctionKeyText(string command){for(int i=0;i<12;i++)if(functionKeys[i]==command)return "F"+(i+1);return "";}
    void ExecuteFunction(string id){switch(id){case "none":return;case "edit":Press(editButton);return;case "source":if(editing&&!PlainText)preview.IsChecked=preview.IsChecked!=true;return;case "dark":Press(quickDark);return;case "wrap":SetWrap(!wordWrap);SavePreferences();return;case "outline":if(!PlainText)Press(outlineButton);return;case "previousTab":CycleTab(-1);return;case "nextTab":CycleTab(1);return;case "zoomIn":Zoom(2);return;case "zoomOut":Zoom(-2);return;case "zoomReset":SetBaseFont(family,16);return;case "check":ToggleCurrentCheck();return;}if(!LiveFormat)return;switch(id){case "heading":Press(headingButton);break;case "paragraph":Press(headingBodyItem);break;case "list":Press(listButton);break;case "bullet":Press(listBulletMenuItem);break;case "number":Press(listNumberMenuItem);break;case "task":Press(taskButton);break;case "quote":Press(quoteButton);break;case "rule":Press(ruleButton);break;case "inline":Press(codeButton);break;case "block":Press(blockButton);break;case "table":ShowCustomTable();break;case "link":Press(linkButton);break;case "image":Press(imageButton);break;case "strike":Press(strikeButton);break;case "mark":Press(markButton);break;case "superscript":LiveScript(true);break;case "subscript":LiveScript(false);break;case "color":if(!OpenHiddenFunctionControl(colorHover))OpenColorPaletteFromKeyboard();break;case "clearColor":ClearTextColor();break;case "size":if(!OpenHiddenFunctionControl(sizes)){sizes.Focus();sizes.IsDropDownOpen=true;}break;case "rowAdd":EditTable(0);break;case "rowRemove":EditTable(1);break;case "columnAdd":EditTable(2);break;case "columnRemove":EditTable(3);break;case "tableDelete":EditTable(4);break;case "tableParagraph":EditTable(5);break;default:if(id.Length==2&&id[0]=='h'&&id[1]>='1'&&id[1]<='6'){int level=id[1]-'1';if(level>=0&&level<headingButtons.Count)Press(headingButtons[level]);}break;}}
    // A narrow window moves the size box and the colour button into the ribbon "»" list; their
    // drop-downs would open detached at the window's top-left corner from there. Open the » list
    // instead (it carries the same size and colour entries) and keep the direct path otherwise.
    bool OpenHiddenFunctionControl(FrameworkElement control){
        if(control==null||control.IsVisible)return false;
        if(ribbonOverflow==null||ribbonOverflowMenu==null||ribbonOverflow.Visibility!=Visibility.Visible||!(ribbonOverflow.ActualWidth>0))return false;
        OpenOverflowMenu(ribbonOverflow,ribbonOverflowMenu);
        return true;
    }
    FrameworkElement ShortcutIcon(string id){if(id.Length==2&&id[0]=='h'&&id[1]>='1'&&id[1]<='6')return Ui.HeadingIcon(id[1]-'0',dark);switch(id){case "heading":return Ui.HeadingIcon(lastHeadingLevel,dark);case "list":case "bullet":return Ui.ListIcon(false,dark);case "number":return Ui.ListIcon(true,dark);case "task":case "check":return Ui.CheckboxIcon();case "rule":return Ui.RuleIcon();case "inline":return Ui.InlineCodeIcon();case "image":return Ui.ImageIcon();case "table":return Ui.TableIcon();case "link":return Ui.LinkIcon();case "strike":return Ui.StrikeIcon();case "mark":return Ui.HighlighterIcon();case "outline":return Ui.OutlineIcon();case "rowAdd":return Ui.TableActionIcon(0);case "rowRemove":return Ui.TableActionIcon(1);case "columnAdd":return Ui.TableActionIcon(2);case "columnRemove":return Ui.TableActionIcon(3);case "tableDelete":return Ui.TableActionIcon(4);case "tableParagraph":return Ui.ParagraphAfterTableIcon();case "edit":case "dark":return new Button {Content=Ui.Icon(id),Style=null,Padding=new Thickness(0),BorderThickness=new Thickness(0),Background=System.Windows.Media.Brushes.Transparent,Foreground=Foreground,Width=20,Height=20,MinHeight=0,IsHitTestVisible=false,Focusable=false};case "block":return new TextBlock {Text="</>",FontSize=12};case "quote":return new TextBlock {Text="❯",FontSize=15};default:return null;}}
    void ShowShortcutSettings(){/* 630 DIP is taller than the work area of a 1366x768 display at 125% (about 582 DIP): fit the window, let the form scroll (it already does) and keep the docked buttons on screen. */Rect ownerArea=WorkAreaFor(this,new Rect(Left,Top,Math.Max(ActualWidth,MinWidth),Math.Max(ActualHeight,MinHeight)));double areaHeight=ownerArea.Height>0?ownerArea.Height:SystemParameters.WorkArea.Height;double height=Math.Min(630,Math.Max(300,areaHeight-40));var window=new Window {Owner=this,Title=T("F1~F12 단축키"),Width=440,Height=height,MinHeight=Math.Min(420,height),MaxHeight=height,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Background,Foreground=Foreground,ShowInTaskbar=false};var panel=new DockPanel {Margin=new Thickness(16)};window.Resources.MergedDictionaries.Add(Resources);window.Content=panel;var description=new TextBlock {Text=T("F키 기능을 선택하세요. 기존 Ctrl 단축키는 유지됩니다."),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(description,Dock.Top);panel.Children.Add(description);var buttons=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};DockPanel.SetDock(buttons,Dock.Bottom);panel.Children.Add(buttons);var combos=new List<ComboBox>();var form=new StackPanel();panel.Children.Add(new ScrollViewer {Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});for(int i=0;i<12;i++){var row=new DockPanel {Margin=new Thickness(0,3,0,3)};row.Children.Add(new TextBlock {Text="F"+(i+1),Width=42,VerticalAlignment=VerticalAlignment.Center});var combo=new ComboBox {MinHeight=28};for(int j=0;j<ShortcutIds.Length;j++){var content=new DockPanel {LastChildFill=true,MinWidth=270};var icon=ShortcutIcon(ShortcutIds[j]);if(icon!=null){icon.Margin=new Thickness(10,0,0,0);icon.VerticalAlignment=VerticalAlignment.Center;DockPanel.SetDock(icon,Dock.Right);content.Children.Add(icon);}content.Children.Add(new TextBlock {Text=T(ShortcutLabels[j]),VerticalAlignment=VerticalAlignment.Center});combo.Items.Add(new ComboBoxItem {Content=content,HorizontalContentAlignment=HorizontalAlignment.Stretch});}combo.SelectedIndex=Math.Max(0,Array.IndexOf(ShortcutIds,functionKeys[i]));row.Children.Add(combo);form.Children.Add(row);combos.Add(combo);}var reset=new Button {Content=T("기본값 복원"),Margin=new Thickness(4,0,4,0),Padding=new Thickness(9,4,9,4)};buttons.Children.Add(reset);reset.Click+=delegate{var defaults=DefaultFunctionKeys();for(int i=0;i<12;i++)combos[i].SelectedIndex=Array.IndexOf(ShortcutIds,defaults[i]);};var cancel=new Button {Content=T("취소"),IsCancel=true,Margin=new Thickness(4,0,4,0),Padding=new Thickness(9,4,9,4)};buttons.Children.Add(cancel);var save=new Button {Content=T("저장"),IsDefault=true,Margin=new Thickness(4,0,4,0),Padding=new Thickness(9,4,9,4)};buttons.Children.Add(save);save.Click+=delegate{for(int i=0;i<12;i++)functionKeys[i]=ShortcutIds[Math.Max(0,combos[i].SelectedIndex)];SavePreferences();if(outlineMenuToggle!=null)outlineMenuToggle.InputGestureText=FunctionKeyText("outline");window.DialogResult=true;};/* CenterOwner centers on the owner, which can sit near an edge, and centers on the restore rectangle when the owner is maximized: keep the whole window inside the work area of the monitor the owner is really on. */window.Loaded+=delegate{Rect area=ownerArea;if(!(area.Width>0)||!(area.Height>0))area=WorkAreaFor(window,new Rect(window.Left,window.Top,window.Width,window.Height));if(area.Width>0&&area.Height>0){window.Left=Math.Max(area.Left,Math.Min(window.Left,area.Right-window.Width));window.Top=Math.Max(area.Top,Math.Min(window.Top,area.Bottom-window.Height));}};window.ShowDialog();}
}}
